<?php
function section_rows():array{return db()->query("SELECT * FROM sections WHERE enabled=1 ORDER BY sort_order,id")->fetchAll();}
function section_content(string $type,int $limit=6):array{$q=db()->prepare("SELECT * FROM content WHERE type=? AND status='published' ORDER BY sort_order,created_at DESC LIMIT ".max(1,min(24,$limit)));$q->execute([$type]);return $q->fetchAll();}

function earning_opportunities():array{
 $q=db()->query("SELECT body FROM sections WHERE type='earning_grid' ORDER BY id LIMIT 1");$body=$q->fetchColumn();if(!is_string($body))return [];
 $lines=array_slice(explode("\n",$body),1);$items=[];
 foreach($lines as $line){$line=trim($line);if($line==='')continue;$p=explode('|',$line,5);$title=trim($p[0]??'');if($title==='')continue;$short=trim($p[1]??'');$image=trim($p[2]??'');$raw=trim($p[3]??'');$detail=$raw!==''&&!preg_match('~^(https?://|/|#)~i',$raw)?$raw:$short;$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$title)),'-'));$items[]=['slug'=>$slug,'title'=>$title,'description'=>$short,'image'=>$image,'detail'=>$detail?:$short];}
 return $items;
}
function earning_opportunity(string $slug):?array{foreach(earning_opportunities() as $item)if(hash_equals($item['slug'],$slug))return $item;return null;}

function render_home_sections():void{
 foreach(section_rows() as $s){$type=$s['type'];$theme=$s['theme']==='dark'?'dark':($s['theme']==='soft'?'soft':'');$cls='section'.($theme?' '.$theme:'').($type==='hero'?' hero':'').($type==='cta'?' cta':'');
 echo '<section'.($type==='earning_grid'?' id="ways-to-earn"':'').' class="'.e($cls).'"><div class="container">';
 if($type==='hero'){echo '<div class="hero-grid"><div>';if($s['eyebrow'])echo '<div class="eyebrow">'.e($s['eyebrow']).'</div>';echo '<h1>'.e($s['title']).'</h1><p class="lead">'.e($s['body']).'</p>';if($s['button_label'])echo '<div class="actions"><a class="btn" href="'.e(registration_url()).'">'.e($s['button_label']).' ↗</a></div>';echo '</div><div class="hero-art">';if($s['image'])echo '<img src="'.e($s['image']).'" alt="'.e($s['title']).'">';else echo '<div class="orbit"></div><div class="art-card"><span>↗</span><small>LIPAHUB</small><strong>Explore new<br>possibilities.</strong><hr><small>Start at your pace</small></div><div class="stamp">LH</div>';echo '</div></div>';}
 elseif($type==='text'||$type==='image_text'){if($s['eyebrow'])echo '<div class="eyebrow">'.e($s['eyebrow']).'</div>';echo '<div class="split"><div><h2>'.e($s['title']).'</h2></div><div><p>'.nl2br(e($s['body'])).'</p>';if($s['button_label'])echo '<a class="plain" href="'.e(registration_url()).'">'.e($s['button_label']).' →</a>';echo '</div></div>';if($type==='image_text'&&$s['image'])echo '<img class="section-image" src="'.e($s['image']).'" alt="">';}
 elseif($type==='earning_grid'){if($s['eyebrow'])echo '<div class="eyebrow">'.e($s['eyebrow']).'</div>';echo '<h2>'.e($s['title']).'</h2>';if($s['body'])echo '<p class="earning-intro">'.e(explode("\n",(string)$s['body'])[0]).'</p>';echo '<div class="earning-card-grid">';foreach(earning_opportunities() as $item){$href=url('index.php?page=opportunity&task='.rawurlencode($item['slug']));echo '<a class="earning-card" href="'.e($href).'"><div class="earning-image">';if($item['image'])echo '<img src="'.e($item['image']).'" alt="'.e($item['title']).'" loading="lazy">';else echo '<span aria-hidden="true">LH</span>';echo '</div><div class="earning-copy"><h3>'.e($item['title']).'</h3><p>'.e($item['description']).'</p><span class="earning-more">View details →</span></div></a>';}echo '</div>';} elseif($type==='feature_grid'){if($s['eyebrow'])echo '<div class="eyebrow">'.e($s['eyebrow']).'</div>';echo '<h2>'.e($s['title']).'</h2><div class="features">';$rows=section_content('faq',3);$fallback=[['Discover activities','Find digital activities and opportunities in one convenient place.'],['Learn as you go','Use practical guides to understand the platform and make informed choices.'],['Move at your pace','Explore available options and take the steps that work for you.']];$lines=array_values(array_filter(explode("\n",$s['body'])));for($i=0;$i<3;$i++){$pair=explode('|',$lines[$i]??'',2);$title=trim($pair[0]??'')?:$fallback[$i][0];$desc=trim($pair[1]??'')?:$fallback[$i][1];echo '<article><i>'.($i===0?'⌁':($i===1?'◎':'↗')).'</i><h3>'.e($title).'</h3><p>'.e($desc).'</p></article>';}echo '</div>';}
 elseif($type==='article_grid'||$type==='country_grid'||$type==='review_grid'){if($s['eyebrow'])echo '<div class="eyebrow '.($theme==='dark'?'light':'').'">'.e($s['eyebrow']).'</div>';echo '<h2>'.e($s['title']).'</h2>';if($s['body'])echo '<p>'.e($s['body']).'</p>';$ctype=$type==='article_grid'?'article':($type==='country_grid'?'country':'review');$rows=section_content($ctype,(int)$s['item_limit']);echo '<div class="'.($type==='review_grid'?'features':($type==='article_grid'?'cards':'countries')).'">';foreach($rows as $r){if($type==='review_grid'){echo '<article><div class="stars">★★★★★</div><p>“'.e($r['body']).'”</p><b>'.e($r['author']?:$r['title']).'</b></article>';}elseif($type==='article_grid'){echo '<a href="'.e(url('index.php?page='.$r['slug'])).'"><div class="cover">';if($r['image'])echo '<img src="'.e($r['image']).'" alt="">';else echo '<b>LH</b>';echo '</div><small class="meta">LIPAHUB GUIDE ↗</small><h3>'.e($r['title']).'</h3><p>'.e($r['excerpt']).'</p></a>';}else echo '<a href="'.e(url('index.php?page='.$r['slug'])).'"><b>'.e($r['title']).' ↗</b><small>'.e($r['excerpt']).'</small></a>';}echo '</div>';}
 elseif($type==='cta'){echo '<div class="cta-inner"><div>';if($s['eyebrow'])echo '<div class="eyebrow light">'.e($s['eyebrow']).'</div>';echo '<h2>'.e($s['title']).'</h2><p>'.e($s['body']).'</p></div><a class="btn white" href="'.e(registration_url()).'">'.e($s['button_label']?:setting('cta_label','Get started')).' ↗</a></div>';}
 elseif($type==='stats'){if($s['eyebrow'])echo '<div class="eyebrow">'.e($s['eyebrow']).'</div>';echo '<h2>'.e($s['title']).'</h2><div class="features">';foreach(array_slice(explode("\n",$s['body']),0,4) as $line){$pair=explode('|',$line,2);echo '<article><h3>'.e($pair[0]??'').'</h3><p>'.e($pair[1]??'').'</p></article>';}echo '</div>';}
 elseif($type==='faq_list'){if($s['eyebrow'])echo '<div class="eyebrow">'.e($s['eyebrow']).'</div>';echo '<h2>'.e($s['title']).'</h2><div class="faq-list">';foreach(section_content('faq',12) as $r)echo '<details><summary>'.e($r['title']).'</summary><p>'.e($r['body']).'</p></details>';echo '</div>';}
 echo '</div></section>';
 }
}
